        nickname = "postMyVariantInfoAnnotation")
    @RequestMapping(value = "/my_variant_info/variant",
        method = RequestMethod.POST,
        produces = "application/json")
    public List<MyVariantInfo> fetchMyVariantInfoAnnotationPOST(
