            return null;
        } else {
            // id is not of hgvsg format
            for (TranscriptConsequence ts : this.getTranscriptConsequences()) {
                if (ts.getHgvsg() != null && !ts.getHgvsg().isEmpty()) {
                    return ts.getHgvsg();
